def mt(rows,cw=None):
    t=Table(rows,colWidths=cw,repeatRows=1,splitByRow=1)
    sc=[("BACKGROUND",(0,0),(-1,0),HBG),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONTNAME",(0,0),(-1,0),BF),("FONTSIZE",(0,0),(-1,0),6.5),("BOTTOMPADDING",(0,0),(-1,0),2),("TOPPADDING",(0,0),(-1,0),2),("GRID",(0,0),(-1,-1),0.3,BC),("VALIGN",(0,0),(-1,-1),"TOP"),("LEFTPADDING",(0,0),(-1,-1),2),("RIGHTPADDING",(0,0),(-1,-1),2),("TOPPADDING",(0,1),(-1,-1),1.5),("BOTTOMPADDING",(0,1),(-1,-1),1.5)]
    for i in range(2,len(rows),2): sc.append(("BACKGROUND",(0,i),(-1,i),EBG))
    t.setStyle(TableStyle(sc)); return t
